import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { useFormik } from "formik";
import { useDispatch, useSelector } from "react-redux";
import { useStateContext } from "../../contexts/ContextProvider";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import CustomForm from "../../components/forms/CustomForm";
import CustomFormItem from "../../components/forms/CustomFormItem";
import CustomInput from "../../components/forms/CustomInput";
import CustomSelectReactSelect from "../../components/forms/CustomSelectReactSelect";
import CustomDatePicker from "../../components/forms/CustomDatePicker";
import useApi from "../../hooks/useApi";
import "react-datepicker/dist/react-datepicker.css";
import Loading from "../../components/Loading";
import countriesApi from "../../api/countriesApi";
import countiesApi from "../../api/countiesApi";
import entitiesApi from "../../api/entitiesApi";
import { Button } from "@heroui/react";
import usersApi from "../../api/usersApi";

const VerifyCorporateUser = () => {
  const navigate = useNavigate();
  const moment = require("moment");

  const user = useSelector((state) => state.Auth.user);
  // const errors = useSelector((state) => state.Auth.errors);

  const [errors, seterrors] = useState([]);

  const [disableResend, setdisableResend] = useState(true);

  const formik = useFormik({
    initialValues: {
      phone: "",
      otp: "",
    },

    validationSchema: Yup.object({
      phone: Yup.string().required().label("Phone number is required"),
      otp: Yup.string().min(4).max(4).required().label("OTP is required"),
    }),

    onSubmit: (values, { resetForm }) => {
      console.log("VALZ", values);

      const data = {
        action: "VerifyCorporateUserOTP",
        otp: values.otp,
        phone: values.phone,
      };

      verifyOTP(data)
    },
  });

  //Verify user OTP

  const verifyCorporateUserOTPApi = useApi(usersApi.usersAction);

  const verifyOTP = async (data) => {
    await verifyCorporateUserOTPApi.request(data);
  };
  useEffect(() => {
    if (verifyCorporateUserOTPApi.data) {
      if (verifyCorporateUserOTPApi.data.user) {
        toast.success(verifyCorporateUserOTPApi.data.response_message);
      } else {
        toast.error(verifyCorporateUserOTPApi.data.response_message);
      }

      if (verifyCorporateUserOTPApi.data.errors) {
        seterrors(verifyCorporateUserOTPApi.data.errors.errors);
        setdisableResend(true)
      }
    }

    console.log("verifyCorporateUserOTPApi.data", verifyCorporateUserOTPApi.data);
  }, [verifyCorporateUserOTPApi.data]);


  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        console.log("x", x);
        toast.error(x);
      });

    }
  }, [errors])

  const { currentColor } = useStateContext();

  const handleResetOTP = () => {};

  return (
    <div className=" grid grid-cols-1 md:grid-cols-12 mt-16 md:mt-4">
      <div className=" col-span-3"></div>
      <div className="grid col-span-6">
        {verifyCorporateUserOTPApi.loading ? (
          <Loading loading={verifyCorporateUserOTPApi.loading} />
        ) : (
          <div className="container m-auto bg-gray-100 w-full ">
            <div className="m-1">
              <ToastContainer position="bottom-center" theme="colored" />
            </div>
            {errors && errors.length ? (
              <div className="bg-red-500 w-full">
                {errors.map((x) => {
                  return (
                    <p className="text-white my-1 font-bold text-lg">{x}</p>
                  );
                })}
              </div>
            ) : (
              <div></div>
            )}
            <div className="text-center py-1">
              <h2 className="mt-2 text-center text-2xl font-extrabold text-gray-900">
                Verify User Phone
              </h2>
            </div>
            <div className=" flex justify-center items-center bg-gray-100 w-full">
              {verifyCorporateUserOTPApi.loading ? (
                <Loading loading={verifyCorporateUserOTPApi.loading} />
              ) : (
                <CustomForm
                  layout="vertical"
                  handleFinish={formik.handleSubmit}
                  className=" w-full"
                >
                  <div className="grid grid-cols-1 md:grid-cols-2  gap-4  justify-center items-center px-5 w-full">
                    <CustomFormItem
                      touched={formik.touched.phone}
                      error={formik.errors.phone}
                    >
                      <CustomInput
                        id="phone"
                        name="phone"
                        onChange={formik.handleChange}
                        placeholder="Enter  phone number"
                        size="large"
                        type="text"
                        value={formik.values.phone}
                      />
                    </CustomFormItem>

                    <CustomFormItem
                      touched={formik.touched.otp}
                      error={formik.errors.otp}
                    >
                      <CustomInput
                        id="otp"
                        name="otp"
                        onChange={formik.handleChange}
                        placeholder="Enter OTP number"
                        size="large"
                        type="text"
                        value={formik.values.otp}
                      />
                    </CustomFormItem>
                  </div>

                  <div className="px-5 my-5 grid grid-cols-1 md:grid-cols-2 gap-4">
                    {disableResend ? (
                      <button
                        disabled={disableResend}
                        onClick={() => handleResetOTP()}
                        className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1 hover:opacity-50  disabled bg-gray-500"
                        type="button"
                      >
                        Resend OTP
                      </button>
                    ) : (
                      <button
                        disabled={disableResend}
                        onClick={() => handleResetOTP()}
                        style={{ background: currentColor }}
                        className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1 hover:opacity-50 "
                        color="primary"
                        type="button"
                      >
                        Resend OTP
                      </button>
                    )}

                    <button
                      style={{ background: currentColor }}
                      className="w-full h-12 my-auto rounded-md m-auto text-white self-center flex-1 hover:opacity-50 "
                      color="primary"
                      type="submit"
                    >
                      Submit
                    </button>
                  </div>
                </CustomForm>
              )}
            </div>
          </div>
        )}
      </div>
      <div className=" col-span-3"></div>
    </div>
  );
};

export default VerifyCorporateUser;
